"""Regime-conditional and confluence rules (hypotheses generated by the RL agent,
Daniel & Moskowitz momentum-crash evidence, and YouTube 'confluence' claims)."""
from __future__ import annotations

import pandas as pd

from .signals import R, Rule, cross_up, first_in, _month_end, trend_template


def reg(name, fn, d, h, fam, src):
    R[name] = Rule(name, fn, d, h, fam, src)


def mkt10(x, up=True):
    def f():
        spy = x.mkt("SPY")
        m = spy.resample("ME").last()
        st = (m > m.rolling(10).mean()).astype(float).reindex(spy.index, method="ffill")
        return x.bcast(st.fillna(0)).astype(bool)
    s = x.get("mkt10", f)
    return s if up else ~s


def rs6(x):
    return x.xs_rank(x.roc(126))


reg("rs_leaders_bull_mkt", lambda x: (rs6(x) >= 0.9) & mkt10(x) & _month_end(x), 1, 21, "regime",
    "RL-v2 + O'Neil: top-decile 6m RS when market above 10m SMA (monthly)")
reg("rs_leaders_bear_mkt", lambda x: (rs6(x) >= 0.9) & mkt10(x, False) & _month_end(x), 1, 21, "regime",
    "Top-decile 6m RS when market below 10m SMA (momentum-crash risk)")
reg("rs_laggards_bull_mkt", lambda x: (rs6(x) <= 0.1) & mkt10(x) & _month_end(x), -1, 21, "regime",
    "Bottom-decile 6m RS in a bull market (avoid)")
reg("rs_laggards_bear_mkt", lambda x: (rs6(x) <= 0.1) & mkt10(x, False) & _month_end(x), 1, 21, "regime",
    "Daniel-Moskowitz: losers rebound in bear/rebound markets (claimed bullish)")
reg("rsi30_bull_mkt", lambda x: first_in((x.rsi(14) < 30) & mkt10(x), 10), 1, 10, "regime",
    "RSI14<30 while market in uptrend")
reg("rsi30_bear_mkt", lambda x: first_in((x.rsi(14) < 30) & mkt10(x, False), 10), 1, 10, "regime",
    "RSI14<30 while market in downtrend")
reg("st_loser_bull_mkt", lambda x: (x.xs_rank(x.roc(5)) <= 0.1) & mkt10(x) & _week_end_(x), 1, 5, "regime",
    "Bottom-decile 5d return, market up")
reg("st_loser_bear_mkt", lambda x: (x.xs_rank(x.roc(5)) <= 0.1) & mkt10(x, False) & _week_end_(x), 1, 5, "regime",
    "Bottom-decile 5d return, market down")


def confluence_breakout(x):
    """O'Neil/Minervini 'everything aligned': trend template + new 52w high + volume + market up."""
    return first_in(trend_template(x) & (x.c > x.hi(252)) & (x.volr() >= 1.5) & mkt10(x), 20)


reg("confluence_breakout", confluence_breakout, 1, 60, "confluence",
    "Trend template + 52w-high breakout + vol>=1.5x + market up")


def confluence_pullback(x):
    """YouTube confluence: uptrend + pullback to support/SMA50 + RSI<40 + bullish candle."""
    from .indicators import candles
    cd = x.candles()
    bull_candle = cd["bull_engulfing"] | cd["hammer"] | cd["piercing"] | cd["morning_star"]
    near50 = (x.l <= x.sma(50) * 1.02) & (x.c >= x.sma(50) * 0.98)
    return first_in((x.c > x.sma(200)) & (x.sma(50) > x.sma(200)) & near50 & (x.rsi(14) < 45) & bull_candle, 10)


reg("confluence_pullback", confluence_pullback, 1, 20, "confluence",
    "Uptrend + pullback to SMA50 + RSI<45 + bullish candle (YouTube confluence)")


def _week_end_(x):
    from .signals import _week_end
    return _week_end(x)


# ---- candidates promoted from the YouTube claimed-strategy tests (iteration: YT backtests)
from .indicators import rsi as _rsi, ema as _ema


def _r10(x):
    return x.get(("rsi", 10), lambda: _rsi(x.c, 10))


reg("yt_rsi10_pullback", lambda x: first_in((x.c > x.sma(200)) & (_r10(x) < 30), 10), 1, 5, "youtube",
    "Rayner Teo: close>SMA200 & RSI(10)<30 (first fire in 10d)")
reg("yt_rsi10_pullback_h10", lambda x: first_in((x.c > x.sma(200)) & (_r10(x) < 30), 10), 1, 10, "youtube",
    "Same, 10-day horizon")
reg("yt_rsi10_pullback_rising200", lambda x: first_in((x.c > x.sma(200)) & (x.sma(200) > x.sma(200).shift(21)) & (_r10(x) < 30), 10),
    1, 5, "youtube", "RSI(10)<30 above a RISING SMA200")
reg("yt_rsi10_any_trend", lambda x: first_in(_r10(x) < 30, 10), 1, 5, "youtube", "RSI(10)<30 without trend filter (ablation)")
reg("yt_rsi10_downtrend", lambda x: first_in((x.c < x.sma(200)) & (_r10(x) < 30), 10), 1, 5, "youtube",
    "RSI(10)<30 BELOW SMA200 (ablation: falling knife)")


def _macd200(x):
    ml, ms, mh = x.macd()
    e200 = _ema(x.c, 200)
    return (x.c > e200) & (ml > ms) & (ml.shift(1) <= ms.shift(1)) & (ml < 0) & (ms < 0)


reg("yt_macd_200ema", _macd200, 1, 15, "youtube", "TradingLab: close>EMA200, MACD bull cross below zero")
